{"query":"trivy scan finding fixed version base image dockerfile","repo_root":"/c/Users/anthoni/projects/entire/anthnel/devdesk","commit":"c1c02f7850da83b68604842f0d957b4f920375bb","tree":"c47bba143d0c287ec24b12fa826e2b1cec6c2d86","profile":"full","results":[{"rank":1,"score":34.2211,"file_path":"internal/scan/trivy.go","start_line":125,"end_line":221,"focus_line":149,"snippet_start_line":125,"snippet_end_line":221,"symbol_start_line":125,"symbol_end_line":221,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/scan/trivy.go:function:parseTrivyOutput","symbol_name":"parseTrivyOutput","qualified_name":"parseTrivyOutput","signature":"func parseTrivyOutput(data []byte) ([]Finding, error)","signals":["path","body","signature","symbol-name","symbol-usage","complete-symbol"],"snippet":"func parseTrivyOutput(data []byte) ([]Finding, error) {
	var report TrivyReport
	if err := json.Unmarshal(data, &report); err != nil {
		return nil, fmt.Errorf("failed to parse trivy output: %w", err)
	}

	var findings []Finding

	for _, result := range report.Results {
		// Process vulnerabilities
		for _, vuln := range result.Vulnerabilities {
			// Build references from PrimaryURL and advisory links
			refs := make([]string, 0, len(vuln.References)+1)
			if vuln.PrimaryURL != "" {
				refs = append(refs, vuln.PrimaryURL)
			}
			for _, r := range vuln.References {
				if r != vuln.PrimaryURL {
					refs = append(refs, r)
				}
			}

			// Build a fix command suggestion when a fixed version is known
			fixCmd := ""
			if vuln.FixedVersion != "" {
				fixCmd = fmt.Sprintf("Update %s to %s", vuln.PkgName, vuln.FixedVersion)
			}

			findings = append(findings, Finding{
				ID:          vuln.VulnerabilityID,
				Title:       vuln.Title,
				Description: vuln.Description,
				Severity:    parseSeverity(vuln.Severity),
				Source:      "trivy",
				File:        result.Target,
				PkgName:     vuln.PkgName,
				Version:     vuln.InstalledVersion,
				FixedIn:     vuln.FixedVersion,
				References:  refs,
				FixCommand:  fixCmd,
			})
		}

		// Process secrets found by Trivy.
		//
		// The report has carried these since TrivySecret was declared; nothing
		// read them, so a secret Trivy found was parsed and dropped. Only the
		// secret stage asks for them (--scanners secret), so there is no risk of
		// the vulnerability stage returning the same finding twice.
		for _, secret := range result.Secrets {
			findings = append(findings, Finding{
				ID:          secret.RuleID,
				Title:       secret.Title,
				Description: secret.Category,
				Severity:    parseSeverity(secret.Severity),
				Source:      SourceTrivySecret,
				File:        result.Target,
				Line:        secret.StartLine,
				Match:       maskSecret(secret.Match),
			})
		}

		// Process licenses found by Trivy
		for _, license := range result.Licenses {
			findings = append(findings, Finding{
				ID:          license.Name,
				Title:       fmt.Sprintf("%s (%s)", license.PkgName, license.Name),
				Description: fmt.Sprintf("License category: %s", license.Category),
				Severity:    parseSeverity(license.Severity),
				Source:      "trivy-license",
				File:        license.FilePath,
				PkgName:     license.PkgName,
			})
		}

		// Process misconfigurations found by Trivy
		for _, misconf := range result.Misconfigurations {
			var miscRefs []string
			if misconf.PrimaryURL != "" {
				miscRefs = append(miscRefs, misconf.PrimaryURL)
			}
			findings = append(findings, Finding{
				ID:          misconf.AVDID,
				Title:       misconf.Title,
				Description: misconf.Desc,
				Severity:    parseSeverity(misconf.Severity),
				Source:      "trivy-misconfig",
				File:        result.Target,
				Line:        misconf.CauseMetadata.StartLine,
				Resolution:  misconf.Resolution,
				References:  miscRefs,
			})
		}
	}

	return findings, nil
}"},{"rank":2,"score":33.1563,"file_path":"internal/cache/image_scan.go","start_line":165,"end_line":176,"focus_line":169,"snippet_start_line":167,"snippet_end_line":176,"symbol_start_line":167,"symbol_end_line":176,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/cache/image_scan.go:method:ImageScanCache.save","symbol_name":"save","qualified_name":"ImageScanCache.save","signature":"func (c *ImageScanCache) save() error","signals":["path","body","symbol-name","graph:callers","complete-symbol"],"snippet":"func (c *ImageScanCache) save() error {
