// bump clears them all — provided the versions can be ordered.
func (g *group) done() Fix {
	fix := g.fix
	sort.Strings(fix.Options)
	if !g.ambiguous {
		fix.Target = highest(fix.Options)
	}
	if fix.Target != "" {
		fix.Command, _ = scan.FixCommand(fix.Ecosystem, fix.Package, fix.Target)
	}
	return fix
}

