	}
	if s.Unclassified > 0 {
		parts = append(parts, strconv.Itoa(s.Unclassified)+" unclassified")
	}
	return strconv.Itoa(s.Fixable()) + " (" + strings.Join(parts, ", ") + ")", theme.HeaderValueStyle, true
}
